        for item in data:
            if 'table' in item and 'title' in item.get('table', {}):
                title = item['table'].get('title', '')
                if 'Maturity Schedule' in title or 'Outstanding' in title:
                    print(f'Title: {title}')
    except Exception as e:
        print(f'Error: {e}')
